export async function getItemFromFoundry(item_id) {
	return await Item.fromDropData({
		type: "Item",
		uuid: item_id,
	});
}

export async function addItem(itemId, instant, slot) {
	const item = await getItemFromFoundry(itemId);
	if (!item) throw new Error(`Starting item not found: ${itemId}`);
	const itemData = item.toObject();
	delete itemData._id;
	itemData._stats ??= {};
	itemData._stats.compendiumSource = item.uuid;
	if (slot) {
		itemData.system.sheet = { ...itemData.system.sheet, ...slot };
	}
	return instant.createEmbeddedDocuments("Item", [itemData]);
}

export async function attrRoll() {
	const roll = new Roll("3d6kh2");
	await roll.evaluate();
	return roll.total;
}

export async function drawFromTable(tableName) {
	const pack = game.packs.get("mausritter.tables");
	const table = (await pack?.getDocuments())?.find(table => table.name === tableName);
	if (!table) throw new Error(`Mausritter table not found: ${tableName}`);

	const buffer = await table.roll();
	const result = buffer.results[0];
	if (!result) return "";
	if (result.name) return result.name;
	if (result.description) {
		return result.description.replace(/<[^>]+>/g, "").trim();
	}
	return "";
}
