const Die = foundry.dice.terms.Die;
const renderTemplate = foundry.applications.handlebars.renderTemplate;

/**
 * Extend the base Actor entity by defining a custom roll data structure which is ideal for the Simple system.
 * @extends {Actor}
 */
export class MausritterActor extends Actor {
	async _postChat(templateData, rolls = []) {
		const chatData = {
			author: game.user.id,
			speaker: ChatMessage.getSpeaker({ actor: this }),
			content: await renderTemplate("systems/mausritter/templates/chat/statroll.html", templateData),
			rolls,
		};
		ChatMessage.applyMode(chatData);
		return ChatMessage.create(chatData);
	}

	async rollStatSelect(statList) {
		const options = statList.map(([key, stat]) => '<option value="' + foundry.utils.escapeHTML(key) + '">' + foundry.utils.escapeHTML(game.i18n.localize('Maus.' + stat.label)) + '</option>').join('');
		const data = await foundry.applications.api.DialogV2.input({window: {title: game.i18n.localize('Maus.RollSelectStat')}, content: '<label>' + game.i18n.localize('Maus.RollSelectStat') + ' <select name="stat">' + options + '</select></label>', rejectClose: false});
		if (data && this.system.stats?.[data.stat]) return this.rollStat(this.system.stats[data.stat]);
	}

	async rollStat(attribute) {
		const data = await foundry.applications.api.DialogV2.input({window: {title: game.i18n.localize('Maus.RollSelectType')}, content: '<label>' + game.i18n.localize('Maus.RollAdvantageDisadvantage') + ' <select name="advantage"><option value="none">' + game.i18n.localize('Maus.RollNone') + '</option><option value="advantage">' + game.i18n.localize('Maus.RollAdvantageDisadvantage') + '</option></select></label>', rejectClose: false});
		if (data) return this.rollAttribute(attribute, data.advantage);
	}

	async rollItem(itemId) {
		const document = this.items.get(itemId);
		if (!document) return ui.notifications.warn('The item is no longer in this inventory.');
		const item = document.toObject();
		if (item.type === 'weapon') {
			const options = ['normal', 'enhanced', 'impaired'].map(value => '<option value="' + value + '">' + game.i18n.localize('Maus.Roll' + value[0].toUpperCase() + value.slice(1)) + '</option>').join('');
			const data = await foundry.applications.api.DialogV2.input({window: {title: game.i18n.localize('Maus.RollSelectType')}, content: '<label>' + game.i18n.localize('Maus.RollDamage') + ' <select name="state">' + options + '</select></label>', rejectClose: false});
			if (data) return this.rollWeapon(item, data.state);
		} else if (item.type === 'spell') {
			return this.rollSpell(item);
		} else return this.chatDesc(item);
	}

	async rollWeapon(item = "", state = "") {
		let die =
			item.system.weapon.selected === 0
				? item.system.weapon.dmg1
				: item.system.weapon.dmg2;

		if (state === "impaired") die = "d4";
		if (state === "enhanced") die = "d12";

		//   this.rollWeapon(item, item.system.weapon.dmg1);
		// else
		// this.rollWeapon(item, item.system.weapon.dmg2);

		const damageRoll = new Roll(die);
		await damageRoll.evaluate();

		const diceData = this.formatDice(damageRoll);

		//Create the pip HTML.
		let pipHtml = "<div style='margin-top: 5px;'>";
		for (let i = 0; i < item.system.pips.max; i++) {
			if (i < item.system.pips.value)
				pipHtml += '<i class="fas fa-circle">&nbsp;</i>';
			else pipHtml += '<i class="far fa-circle">&nbsp;</i>';
		}
		pipHtml += "</div>";

		const templateData = {
			actor: this,
			data: {
				diceTotal: {
					damageValue: damageRoll.total,
					damageRoll: damageRoll,
				},
			},
			item: item,
			pip: pipHtml,
			rollTitle: game.i18n.localize("Maus.RollDamage"), //The title of the roll.
			rollText: damageRoll.total, //What is printed within the roll amount.
			damageDice: die,
			weaponState: game.i18n.localize(
				`Maus.Roll${state.charAt(0).toUpperCase()}${state.slice(1)}`,
			),
			isWeapon: true,
			diceData,
		};

		return this._postChat(templateData, [damageRoll]);
	}

	async rollSpell(item = "", power) {
		if (power !== undefined) {
			power = Number(power);
			if (!Number.isSafeInteger(power) || power < 1) throw new Error("Spell power must be a positive whole number.");
		}
		const document = this.items.get(item._id);
		if (document?.type !== "spell") return ui.notifications.warn("The spell is no longer in this inventory.");
		const maxUses = Number(document.system.pips.max);
		if (!Number.isSafeInteger(maxUses) || maxUses < 1) return ui.notifications.warn("Set the spell's maximum usage to a positive whole number before casting.");
		const maxPower = game.settings.get("mausritter", "limitSpellPowerToRemainingUses")
			? Math.max(0, Math.floor(maxUses - Math.max(0, Number(document.system.pips.value) || 0))) : maxUses;
		if (maxPower === 0 || (game.settings.get("mausritter", "blockExhaustedSpells") && document.system.pips.value >= maxUses)) return ui.notifications.warn("This spell is exhausted. Clear a usage mark before casting again.");
		if (power === undefined) {
			const data = await foundry.applications.api.DialogV2.input({
				window: {title: game.i18n.localize("Maus.RollPowerDesc")},
				content: `<label>${game.i18n.localize("Maus.RollPowerDesc")} (1–${maxPower}) <range-picker name="power" min="1" max="${maxPower}" step="1" value="1"></range-picker></label>`,
				rejectClose: false,
			});
			// Recheck the live Item after the dialog, including deletion or changed usage limits.
			if (data) return this.rollSpell(item, data.power);
			return;
		}
		if (power > maxPower) return ui.notifications.warn(`Spell power cannot exceed its current limit (${maxPower}).`);
		const die = `${power}d6`;

		const damageRoll = new Roll(die);
		await damageRoll.evaluate();

		const diceData = this.formatDice(damageRoll);

		let rollDiv = "";

		let usage = 0;
		let miscast = 0;

		for (let i = 0; i < Number.parseInt(power, 10); i++) {
			if (i > 0) rollDiv += `, ${diceData.dice[i].result}`;
			else rollDiv += `${diceData.dice[i].result}`;

			if (diceData.dice[i].result >= 4) {
				usage++;
				if (diceData.dice[i].result === 6) {
					miscast++;
				}
			}
		}

		if (usage) {
			const value = Math.min(document.system.pips.max, Math.max(0, Number(document.system.pips.value) || 0) + usage);
			if (value !== document.system.pips.value) {
				const updated = await document.update({"system.pips.value": value});
				if (!updated) throw new Error("The spell's usage marks could not be saved.");
			}
		}
		item = document.toObject();

		if (item.system.description == null) {
			item.system.description = "";
		}

		item.system.description = item.system.description
			.split(game.i18n.localize("Maus.RollDiceKeyword"))
			.join(
				`<strong style='text-decoration:underline' class='red'>${power}</strong>`,
			);
		item.system.description = item.system.description
			.split(game.i18n.localize("Maus.RollSumKeyword"))
			.join(
				`<strong style='text-decoration:underline' class='red'>${damageRoll.total}</strong>`,
			);
		item.system.description += `<h2>${game.i18n.localize("Maus.RollUsage")}: <strong>${usage}</strong></h2>`;
		if (miscast) {
			let miscastDesc = game.i18n.localize("Maus.RollMiscastDesc");
			miscastDesc = miscastDesc.replace("!miscast!", `${miscast}`);
			item.system.description += `<h2>${game.i18n.localize("Maus.RollMiscast")}: <strong>${miscast}</strong> </h2>${miscastDesc}`;
		}

		//Create the pip HTML.
		let pipHtml = "<div style='margin-top: 5px;'>";
		for (let i = 0; i < item.system.pips.max; i++) {
			if (i < item.system.pips.value)
				pipHtml += '<i class="fas fa-circle">&nbsp;</i>';
			else pipHtml += '<i class="far fa-circle">&nbsp;</i>';
		}
		pipHtml += "</div>";

		const templateData = {
			actor: this,
			data: {
				diceTotal: {
					damageValue: damageRoll.total,
					damageRoll: damageRoll,
				},
				rollDiv: rollDiv,
			},
			item: item,
			pip: pipHtml,
			isSpell: true,
			isWeapon: true,
			rollTitle: `${game.i18n.localize("Maus.RollSum")}|${game.i18n.localize("Maus.RollDice")}`, //The title of the roll.
			rollText: `${damageRoll.total}|${power}`, //What is printed within the roll amount.
			sum: damageRoll.total,
			dice: power,
			diceData,
		};

		return this._postChat(templateData, [damageRoll]);
	}

	async rollAttribute(attribute, advantage, item = "", rollOver = false) {
		let attributeName =
			attribute.label?.charAt(0).toUpperCase() +
			attribute.label?.toLowerCase().slice(1);
		if (!attribute.label && Number.isNaN(attributeName))
			attributeName =
				attribute.charAt(0)?.toUpperCase() + attribute.toLowerCase().slice(1);

		// Roll
		const diceformular = "1d20";

		const r = new Roll(diceformular, {});
		await r.evaluate();

		const _rSplit = `${r.total}`.split("");

		//Advantage roll
		const a = new Roll(diceformular, {});
		await a.evaluate();

		let damageRoll = 0;
		if (item?.type === "weapon") {
			damageRoll = new Roll(item.system.damage);
			await damageRoll.evaluate();
		}

		// Format Dice
		const diceData = this.formatDice(r);

		let mod = 0;
		if (attribute.mod > 0) mod = attribute.mod;

		const targetValue =
			attribute.value + mod + (item === "" ? 0 : item.system.bonus);

		//Here's where we handle the result text.
		let resultText = "";

		if (rollOver === true) {
			resultText =
				r.total >= targetValue
					? game.i18n.localize("Maus.RollSuccess")
					: game.i18n.localize("Maus.RollFailure");
		} else {
			resultText =
				r.total <= targetValue
					? game.i18n.localize("Maus.RollSuccess")
					: game.i18n.localize("Maus.RollFailure");
		}

		const templateData = {
			actor: this,
			stat: {
				name: game.i18n.localize(`Maus.${attributeName}`).toUpperCase(),
			},
			data: {
				diceTotal: {
					value: r.total,
					advantageValue: a.total,
					damageValue:
						typeof damageRoll === "number" ? damageRoll : damageRoll.total,
					damageRoll: damageRoll,
				},
				resultText: {
					value: resultText,
				},
				isCreature: {
					value: this.type === "hireling",
				},
			},
			target: attribute.value,
			mod: mod,
			item: item,
			targetValue: targetValue,
			useSkill: item?.type === "skill",
			isWeapon: item?.type === "weapon",
			advantage: advantage === "advantage",
			diceData,
		};

		return this._postChat(templateData, [r, ...(advantage === "advantage" ? [a] : []), ...(damageRoll instanceof Roll ? [damageRoll] : [])]);
	}

	formatDice(diceRoll) {
		const diceData = { dice: [] };

		if (diceRoll != null) {
			const pushDice = (diceData, total, faces, color) => {
				let img = null;
				if ([4, 6, 8, 10, 12, 20].indexOf(faces) > -1) {
					img = `../icons/svg/d${faces}-grey.svg`;
				}
				diceData.dice.push({
					img: img,
					result: total,
					dice: true,
					color: color,
				});
			};

			for (let i = 0; i < diceRoll.terms.length; i++) {
				if (diceRoll.terms[i] instanceof Die) {
					const pool = diceRoll.terms[i].results;
					const faces = diceRoll.terms[i].faces;

					for (const pooldie of pool) {
						if (pooldie.discarded) {
							pushDice(diceData, pooldie.result, faces, "#777");
						} else {
							pushDice(diceData, pooldie.result, faces, "white");
						}
					}
				} else if (typeof diceRoll.terms[i] === "string") {
					const parsed = Number.parseInt(diceRoll.terms[i], 10);
					if (!Number.isNaN(parsed)) {
						diceData.dice.push({
							img: null,
							result: parsed,
							dice: false,
							color: "white",
						});
					} else {
						diceData.dice.push({
							img: null,
							result: diceRoll.terms[i],
							dice: false,
						});
					}
				} else if (typeof diceRoll.terms[i] === "number") {
					const parsed = Number.parseInt(diceRoll.terms[i], 10);
					if (!Number.isNaN(parsed)) {
						diceData.dice.push({
							img: null,
							result: parsed,
							dice: false,
							color: "white",
						});
					} else {
						diceData.dice.push({
							img: null,
							result: diceRoll.terms[i],
							dice: false,
						});
					}
				}
			}
		}

		return diceData;
	}

	// Print the item description into the chat.
	chatDesc(item) {
		let itemName =
			item.name?.charAt(0).toUpperCase() + item.name?.toLowerCase().slice(1);
		if (!item.name && Number.isNaN(itemName))
			itemName = item.charAt(0)?.toUpperCase() + item.toLowerCase().slice(1);

		//Create the pip HTML.
		let pipHtml = "<div style='margin-top: 5px;'>";
		for (let i = 0; i < item.system.pips.max; i++) {
			if (i < item.system.pips.value)
				pipHtml += '<i class="fas fa-circle">&nbsp;</i>';
			else pipHtml += '<i class="far fa-circle">&nbsp;</i>';
		}
		pipHtml += "</div>";

		if (item.system.description == null) {
			item.system.description = "";
		} else if (item.system.description.length > 0) {
			item.system.description += "<br/>";
		}
		if (item.type === "condition") {
			item.system.description += `${item.system.desc}<br/><strong>Clear: </strong>${item.system.clear}`;
		}

		const templateData = {
			actor: this,
			stat: {
				name: itemName.toUpperCase(),
			},
			item: item,
			pip: pipHtml,
			onlyDesc: true,
		};

		return this._postChat(templateData, []);
	}
}
