import {createMausritterMacro, rollItemMacro, rollStatMacro, rollWeather, generateHex, generateNpc} from "./macros.js";
import {migrateSheetReferences, migrateMacros} from "./migration.js";
import {actorDataModels, itemDataModels} from "./data-models.js";
// Import Modules
import { MausritterActor } from "./actor/actor.js";
import { MausritterActorSheet } from "./actor/actor-sheet.js";
import { autoCreateCharacter } from "./actor/create-character/create-character.js";
import { MausritterCreatureSheet } from "./actor/creature-sheet.js";
import { MausritterHirelingSheet } from "./actor/hireling-sheet.js";
import { MausritterStorageSheet } from "./actor/storage-sheet.js";
import { MausritterItem } from "./item/item.js";
import { MausritterItemSheet } from "./item/item-sheet.js";
import { registerSettings } from "./settings.js";

const Actors = foundry.documents.collections.Actors;
const Items = foundry.documents.collections.Items;

Hooks.once("init", async () => {
	game.mausritter = {
		MausritterActor,
		MausritterItem,
		rollItemMacro,
		rollStatMacro,
		autoCreateCharacter,
		rollWeather, generateHex, generateNpc,
	};

	registerSettings();
	game.settings.register("mausritter", "sheetMigrationVersion", {scope: "world", config: false, type: Number, default: 0});
	game.settings.register("mausritter", "macroMigrationVersion", {scope: "world", config: false, type: Number, default: 0});


	// Define custom Entity classes
	CONFIG.Actor.documentClass = MausritterActor;
	CONFIG.Item.documentClass = MausritterItem;
	Object.assign(CONFIG.Actor.dataModels, actorDataModels);
	Object.assign(CONFIG.Item.dataModels, itemDataModels);

	// Define table data for character generator
	CONFIG.MAUSRITTER = {};

	CONFIG.MAUSRITTER.tables = {
		tables: "Tables",
		birthsign: "Birthsign",
		physicalDetail: "Physical detail",
		coatPattern: "Mousy Coat Pattern",
		coatColor: "Mousy Coat Color",
		firstName: "Mousy Names - Birthname",
		lastName: "Mousy Names - Matriname",
		npcAppearance: "Non-player mice - Appearance",
		npcBirthsign: "Non-player mice - Birthsign and Disposition",
		npcQuirk: "Non-player mice - Quirk",
		npcSocial: "Non-player mice - Social position and Payment for service",
		npcWants: "Non-player mice - Wants",
		npcRelationship: "Non-player mice - Relationship",
	};

	// Register sheet application classes

	Actors.registerSheet("mausritter", MausritterActorSheet, {
		types: ["character"],
		makeDefault: true, themes: null,
	});
	Actors.registerSheet("mausritter", MausritterHirelingSheet, {
		types: ["hireling"],
		makeDefault: true, themes: null,
	});
	Actors.registerSheet("mausritter", MausritterCreatureSheet, {
		types: ["creature"],
		makeDefault: true, themes: null,
	});
	Actors.registerSheet("mausritter", MausritterStorageSheet, {
		types: ["storage"],
		makeDefault: true, themes: null,
	});

	Items.registerSheet("mausritter", MausritterItemSheet, { makeDefault: true, themes: null });

	Handlebars.registerHelper("toLowerCase", (str) => str.toLowerCase());

	CONFIG.Combat.initiative = {
		formula: "-1d20+@stats.dexterity.value",
		decimals: 2,
	};
});

/**
 * Set default values for new actors' tokens
 */
Hooks.on("preCreateActor", (document, data) => {
 const defaults = {
  name: data.name,
  bar1: {attribute: 'health'}, bar2: {attribute: 'stats.strength'},
  displayName: CONST.TOKEN_DISPLAY_MODES.OWNER_HOVER,
  displayBars: CONST.TOKEN_DISPLAY_MODES.OWNER_HOVER,
  disposition: data.type === 'creature' ? CONST.TOKEN_DISPOSITIONS.HOSTILE : CONST.TOKEN_DISPOSITIONS.NEUTRAL,
 };
 if (data.type === 'character') Object.assign(defaults, {sight: {enabled: true}, actorLink: true});
 document.updateSource({prototypeToken: foundry.utils.mergeObject(defaults, data.prototypeToken ?? {})});
});

Hooks.once("ready", async () => {
	game.mausritter.ready = migrateSheetReferences().then(migrateMacros);
	game.mausritter.ready.catch(error => { console.error("Mausritter migration failed", error); ui.notifications.error("Mausritter could not migrate saved sheets or bundled macros. See console; it will retry next launch."); });
	// Wait to register hotbar drop hook on ready so that modules could register earlier if they want to
	Hooks.on("hotbarDrop", (_bar, data, slot) => {
		if (data.type === "Item") {
			createMausritterMacro(data, slot).catch(error => ui.notifications.error(error.message));
			return false;
		}
	});
});
