const {SchemaField, NumberField, StringField, BooleanField, HTMLField, AnyField} = foundry.data.fields;
const number = (initial = 0) => new NumberField({required: true, nullable: true, initial});
const string = (initial = "") => new StringField({required: true, nullable: true, trim: false, initial});
const html = () => new HTMLField({required: true, nullable: true, initial: ""});

class MausritterData extends foundry.abstract.TypeDataModel {
	static _preCleanData(data, options, state) {
		super._preCleanData(data, options, state);
		// Existing worlds and importers can contain additional system fields. Keep them on save/export.
		options.prune = false;
	}
}

class ActorData extends MausritterData {
	static defineSchema() {
		return {
			health: new SchemaField({value: number(), min: number(), max: number()}),
			hits: new SchemaField({value: number(2), max: number(2)}),
			armor: number(), biography: html(), notes: html(),
			description: new SchemaField({disposition: string()}),
		};
	}
}

class CreatureData extends ActorData {
	static defineSchema() {
		return {...super.defineSchema(), stats: new SchemaField(Object.fromEntries(
			["Strength", "Dexterity", "Will"].map(label => [label.toLowerCase(),
				new SchemaField({value: number(), label: string(label), max: number()})])
		))};
	}
}

class CharacterData extends CreatureData {
	static defineSchema() {
		return {...super.defineSchema(),
			description: new SchemaField({background: string("Description"), birthsign: string(), coat: string(), look: string()}),
			level: new SchemaField({value: number(1), xp: number()}),
			pips: new SchemaField({value: number()}),
			grit: new SchemaField({value: number(), ignored: string()}),
			other: new SchemaField({grit: new SchemaField({value: number()})}),
		};
	}
}

class HirelingData extends CreatureData {
	static defineSchema() {
		return {...super.defineSchema(),
			// Present in the existing sheet, but absent from the old template's defaults.
			level: new SchemaField({value: number(), xp: number()}, {required: false}),
			grit: new SchemaField({value: number()}, {required: false}),
		};
	}
}

class StorageActorData extends ActorData {
	static defineSchema() {
		return {...super.defineSchema(), size: new SchemaField({width: number(3), height: number(2)}), storeDiv: string()};
	}
}

class ItemData extends MausritterData {
	static defineSchema() {
		return {
			description: html(), color: string("white"),
			equipped: new BooleanField({required: false, initial: undefined}),
			sheet: new SchemaField({
				active: new BooleanField(), currentX: number(), currentY: number(), initialX: number(), initialY: number(),
				xOffset: number(), yOffset: number(), rotation: number(), curWidth: number(1), curHeight: number(1), zIndex: number(1),
			}),
			pips: new SchemaField({value: number(), max: number(), html: string()}),
			size: new SchemaField({width: number(1), height: number(1), x: string("9em"), y: string("9em"), aspect: number(1)}),
		};
	}
}

class GearData extends ItemData {
	static defineSchema() {
		return {...super.defineSchema(), weight: number(), cost: number(), tag: string()};
	}
}

class CarriedItemData extends GearData {
	static defineSchema() {
		return {...super.defineSchema(), placement: string("hand")};
	}
}

class WeaponData extends CarriedItemData {
	static defineSchema() {
		return {...super.defineSchema(), weapon: new SchemaField({
			dmg1: string("d6"), dmg2: string(), selected: number(), canSwap: new BooleanField(),
		})};
	}
}

class ArmorData extends GearData {
	static defineSchema() {
		return {...super.defineSchema(), armor: new SchemaField({value: number(1)})};
	}
}

class StorageItemData extends GearData {
	static defineSchema() {
		return {...super.defineSchema(), store: new SchemaField({
			// This field historically accepts both text and numeric quantities.
			value: new AnyField({required: true, nullable: true, initial: "0", validate: value =>
				typeof value === "string" || (typeof value === "number" && Number.isFinite(value))}),
			max: number(25),
		})};
	}
}

class ConditionData extends ItemData {
	static defineSchema() {
		return {...super.defineSchema(), clear: string(), desc: string()};
	}
}

class SpellData extends ItemData {
	static defineSchema() {
		return {...super.defineSchema(), tag: string(), isSpell: new BooleanField({initial: true}),
			cost: new NumberField({required: false, nullable: true, initial: undefined})};
	}
}

export const actorDataModels = {character: CharacterData, hireling: HirelingData, creature: CreatureData, storage: StorageActorData};
export const itemDataModels = {item: CarriedItemData, weapon: WeaponData, armor: ArmorData, storage: StorageItemData, condition: ConditionData, spell: SpellData};
