import { MausritterBaseActorSheet } from "./actor-sheet.js";
export class MausritterStorageSheet extends MausritterBaseActorSheet {
	static DEFAULT_OPTIONS = { classes: ["storage"], position: { width: 475, height: 500 }, window: { resizable: false } };
	static PARTS = { body: { template: "systems/mausritter/templates/actor/storage-sheet.html", scrollable: [".sheet-body"] } };
	static TABS = { primary: { initial: "storage", tabs: [{ id: "storage" }, { id: "notes" }, { id: "options" }] } };

	async _prepareContext(options) {
		const context = await super._prepareContext(options);
		const { width, height } = context.system.size;
		context.system.size.divWidth = width * 130 + 35;
		context.system.size.divHeight = height * 130 + 35;
		context.system.storeDiv = "";
		for (let y = 0; y < height; y++) {
			for (let x = 0; x < width; x++) context.system.storeDiv += `<div class="item-slot-dashed" style="transform:translate3d(${x * 130 - (width - 1) * 65}px,${y * 130 - (height - 1) * 65}px,0)"><div class="item-bag-text">${y * width + x + 1}</div></div>`;
		}
		return context;
	}

	_prepareSubmitData(event, form, formData, updateData) {
		const data = super._prepareSubmitData(event, form, formData, updateData);
		for (const axis of ["width", "height"]) {
			if (!(axis in (data.system?.size ?? {}))) continue;
			const value = Number(data.system.size[axis]);
			if (!Number.isSafeInteger(value) || value < 1) throw new Error("Storage dimensions must be positive whole numbers.");
			data.system.size[axis] = value;
		}
		return data;
	}

	async _onRender(context, options) {
		await super._onRender(context, options);
		this.setPosition({ width: context.system.size.width * 130 + 80, height: context.system.size.height * 130 + 230 });
	}
}
