const { HandlebarsApplicationMixin } = foundry.applications.api;
const { ItemSheetV2 } = foundry.applications.sheets;

export class MausritterItemSheet extends HandlebarsApplicationMixin(ItemSheetV2) {
	static DEFAULT_OPTIONS = {
		classes: ["mausritter", "sheet", "item", "themed", "theme-light"],
		position: { width: 520, height: 480 },
		window: { resizable: true },
		form: { submitOnChange: true },
	};
	static PARTS = { body: { template: "systems/mausritter/templates/item/item-item-sheet.html", scrollable: [".sheet-body"] } };
	static TABS = { primary: { initial: "description", tabs: [{ id: "description" }] } };

	_configureRenderParts(options) {
		const parts = super._configureRenderParts(options);
		parts.body.template = `systems/mausritter/templates/item/item-${this.item.type}-sheet.html`;
		return parts;
	}

	async _prepareContext(options) {
		const context = await super._prepareContext(options);
		return Object.assign(context, this.item.toObject(), {
			owner: this.item.isOwner,
			enriched: { description: await foundry.applications.ux.TextEditor.implementation.enrichHTML(this.item.system.description ?? "", { secrets: this.item.isOwner, relativeTo: this.item }) },
		});
	}

	async _onRender(context, options) {
		await super._onRender(context, options);
		this.changeTab(this.tabGroups.primary, "primary", { force: true });
	}
}
