export function itemMacroCommand(name) {
	return `game.mausritter.rollItemMacro(${JSON.stringify(name)})`;
}

export async function createMausritterMacro(dropData, slot) {
	const item = await Item.implementation.fromDropData(dropData);
	if (!item?.parent || item.parent.documentName !== "Actor") return ui.notifications.warn("You can only create macro buttons for owned Items");
	const command = itemMacroCommand(item.name);
	const macro = game.macros.find(m => m.name === item.name && m.command === command && m.isAuthor)
		?? await Macro.create({ name: item.name, img: item.img, type: "script", command, flags: { "mausritter.itemMacro": true } });
	return game.user.assignHotbarMacro(macro, slot);
}

export function rollItemMacro(itemName) {
	const actor = ChatMessage.getSpeakerActor(ChatMessage.getSpeaker());
	const item = actor?.items.find(i => i.name === itemName);
	if (!item) return ui.notifications.warn(`Your controlled Actor does not have an item named ${itemName}`);
	return actor.rollItem(item.id);
}

export function rollStatMacro() {
	const actor = ChatMessage.getSpeakerActor(ChatMessage.getSpeaker());
	if (!actor?.system.stats) return ui.notifications.warn("Select an actor with attributes to roll.");
	return actor.rollStatSelect(Object.entries(actor.system.stats));
}

export async function rollWeather() {
	const seasons = ["Summer", "Autumn", "Winter", "Spring"];
	const data = await foundry.applications.api.DialogV2.input({ window: { title: "Select Season" }, content: `<label>Season <select name="season">${seasons.map(s => `<option>${s}</option>`).join("")}</select></label>`, rejectClose: false });
	if (!data || !seasons.includes(data.season)) return null;
	return ChatMessage.create({ content: `<h2>Today's Weather:</h2><b>${foundry.utils.escapeHTML(await drawFromTable(`Weather ${data.season}`))}</b>`, whisper: ChatMessage.getWhisperRecipients("GM").map(u => u.id) });
}

export async function generateHex() {
	const types = ["Countryside", "Forest", "River", "Human Town"];
	const data = await foundry.applications.api.DialogV2.input({ window: { title: "Select Type" }, content: `<label>Select or Roll Hex Type <select name="type">${["Random", ...types].map(s => `<option>${s}</option>`).join("")}</select></label>`, rejectClose: false });
	if (!data) return null;
	const type = data.type === "Random" ? types[Math.floor(Math.random() * types.length)] : data.type;
	if (!types.includes(type)) throw new Error("Invalid hex type.");
	const landmark = await drawFromTable(`Hex - ${type}`);
	const details = await drawFromTable("Hex - Landmark Details");
	return ChatMessage.create({ content: `<h2>${type}:</h2><p><b>Landmark:</b> ${foundry.utils.escapeHTML(landmark)}</p><p><b>Details:</b> <i>${foundry.utils.escapeHTML(details)}</i></p>`, whisper: ChatMessage.getWhisperRecipients("GM").map(u => u.id) });
}

export async function generateNpc() {
	const tables = CONFIG.MAUSRITTER.tables;
	const description = { disposition: await drawFromTable(tables.npcBirthsign) };
	let notes = "";
	for (const [label, key] of [["Social position and Payment for service", "npcSocial"], ["Appearance", "npcAppearance"], ["Quirk", "npcQuirk"], ["Wants", "npcWants"], ["Relationship", "npcRelationship"]]) {
		notes += `<p><b>${label}:</b> ${foundry.utils.escapeHTML(await drawFromTable(tables[key]))}</p>`;
	}
	const name = `${await drawFromTable(tables.firstName)} ${await drawFromTable(tables.lastName)}`;
	const stats = {};
	for (const key of ["dexterity", "strength", "will"]) {
		const { total } = await new Roll("2d6").evaluate();
		stats[key] = { max: total, value: total };
	}
	const { total: health } = await new Roll("1d6").evaluate();
	const actor = await Actor.create({ name, type: "hireling", system: { description, notes, stats, health: { max: health, value: health } } });
	await actor.sheet.render({ force: true });
	return actor;
}
import { drawFromTable } from "./actor/create-character/foundry-client.js";
